        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug arises from attempting to use the burst capability (xmit_more) on virtual devices, such as bonding, which do not support this feature. This can lead to multiple queueing of skb on a qdisc, resulting in various list corruptions and instability in packet transmission.

        Commit message:
        net: pktgen: disable xmit_clone on virtual devices

Trying to use burst capability (aka xmit_more) on a virtual device
like bonding is not supported.

For example, skb might be queued multiple times on a qdisc, with
various list corruptions.

Fixes: 38b2cf2982dc ("net: pktgen: packet bursting via skb->xmit_more")
Signed-off-by: Eric Dumazet <edumazet@google.com>
Cc: Alexei Starovoitov <ast@plumgrid.com>
Acked-by: Alexei Starovoitov <ast@plumgrid.com>
Signed-off-by: David S. Miller <davem@davemloft.net>  

        Patch:

 static ssize_t pktgen_if_write(struct file *file,
 			       const char __user * user_buffer, size_t count,
 			       loff_t * offset)
 {
 	struct seq_file *seq = file->private_data;
 	struct pktgen_dev *pkt_dev = seq->private;
 	int i, max, len;
 	char name[16], valstr[32];
 	unsigned long value = 0;
 	char *pg_result = NULL;
 	int tmp = 0;
 	char buf[128];

 	pg_result = &(pkt_dev->result[0]);

 	if (count < 1) {
 		pr_warn("wrong command format\n");
 		return -EINVAL;
 	}

 	max = count;
 	tmp = count_trail_chars(user_buffer, max);
 	if (tmp < 0) {
 		pr_warn("illegal format\n");
 		return tmp;
 	}
 	i = tmp;

 	/* Read variable name */

 	len = strn_len(&user_buffer[i], sizeof(name) - 1);
 	if (len < 0)
 		return len;

 	memset(name, 0, sizeof(name));
 	if (copy_from_user(name, &user_buffer[i], len))
 		return -EFAULT;
 	i += len;

 	max = count - i;
 	len = count_trail_chars(&user_buffer[i], max);
 	if (len < 0)
 		return len;

 	i += len;

 	if (debug) {
 		size_t copy = min_t(size_t, count, 1023);
 		char tb[copy + 1];
 		if (copy_from_user(tb, user_buffer, copy))
 			return -EFAULT;
 		tb[copy] = 0;
 		pr_debug("%s,%lu  buffer -:%s:-\n",
 			 name, (unsigned long)count, tb);
 	}

 	if (!strcmp(name, "min_pkt_size")) {
 		len = num_arg(&user_buffer[i], 10, &value);
 		if (len < 0)
 			return len;

 		i += len;
 		if (value < 14 + 20 + 8)
 			value = 14 + 20 + 8;
 		if (value != pkt_dev->min_pkt_size) {
 			pkt_dev->min_pkt_size = value;
 			pkt_dev->cur_pkt_size = value;
 		}
 		sprintf(pg_result, "OK: min_pkt_size=%u",
 			pkt_dev->min_pkt_size);
 		return count;
 	}

 	if (!strcmp(name, "max_pkt_size")) {
 		len = num_arg(&user_buffer[i], 10, &value);
 		if (len < 0)
 			return len;

 		i += len;
 		if (value < 14 + 20 + 8)
 			value = 14 + 20 + 8;
 		if (value != pkt_dev->max_pkt_size) {
 			pkt_dev->max_pkt_size = value;
 			pkt_dev->cur_pkt_size = value;
 		}
 		sprintf(pg_result, "OK: max_pkt_size=%u",
 			pkt_dev->max_pkt_size);
 		return count;
 	}

 	/* Shortcut for min = max */

 	if (!strcmp(name, "pkt_size")) {
 		len = num_arg(&user_buffer[i], 10, &value);
 		if (len < 0)
 			return len;

 		i += len;
 		if (value < 14 + 20 + 8)
 			value = 14 + 20 + 8;
 		if (value != pkt_dev->min_pkt_size) {
 			pkt_dev->min_pkt_size = value;
 			pkt_dev->max_pkt_size = value;
 			pkt_dev->cur_pkt_size = value;
 		}
 		sprintf(pg_result, "OK: pkt_size=%u", pkt_dev->min_pkt_size);
 		return count;
 	}

 	if (!strcmp(name, "debug")) {
 		len = num_arg(&user_buffer[i], 10, &value);
 		if (len < 0)
 			return len;

 		i += len;
 		debug = value;
 		sprintf(pg_result, "OK: debug=%u", debug);
 		return count;
 	}

 	if (!strcmp(name, "frags")) {
 		len = num_arg(&user_buffer[i], 10, &value);
 		if (len < 0)
 			return len;

 		i += len;
 		pkt_dev->nfrags = value;
 		sprintf(pg_result, "OK: frags=%u", pkt_dev->nfrags);
 		return count;
 	}
 	if (!strcmp(name, "delay")) {
 		len = num_arg(&user_buffer[i], 10, &value);
 		if (len < 0)
 			return len;

 		i += len;
 		if (value == 0x7FFFFFFF)
 			pkt_dev->delay = ULLONG_MAX;
 		else
 			pkt_dev->delay = (u64)value;

 		sprintf(pg_result, "OK: delay=%llu",
 			(unsigned long long) pkt_dev->delay);
 		return count;
 	}
 	if (!strcmp(name, "rate")) {
 		len = num_arg(&user_buffer[i], 10, &value);
 		if (len < 0)
 			return len;

 		i += len;
 		if (!value)
 			return len;
 		pkt_dev->delay = pkt_dev->min_pkt_size*8*NSEC_PER_USEC/value;
 		if (debug)
 			pr_info("Delay set at: %llu ns\n", pkt_dev->delay);

 		sprintf(pg_result, "OK: rate=%lu", value);
 		return count;
 	}
 	if (!strcmp(name, "ratep")) {
 		len = num_arg(&user_buffer[i], 10, &value);
 		if (len < 0)
 			return len;

 		i += len;
 		if (!value)
 			return len;
 		pkt_dev->delay = NSEC_PER_SEC/value;
 		if (debug)
 			pr_info("Delay set at: %llu ns\n", pkt_dev->delay);

 		sprintf(pg_result, "OK: rate=%lu", value);
 		return count;
 	}
 	if (!strcmp(name, "udp_src_min")) {
 		len = num_arg(&user_buffer[i], 10, &value);
 		if (len < 0)
 			return len;

 		i += len;
 		if (value != pkt_dev->udp_src_min) {
 			pkt_dev->udp_src_min = value;
 			pkt_dev->cur_udp_src = value;
 		}
 		sprintf(pg_result, "OK: udp_src_min=%u", pkt_dev->udp_src_min);
 		return count;
 	}
 	if (!strcmp(name, "udp_dst_min")) {
 		len = num_arg(&user_buffer[i], 10, &value);
 		if (len < 0)
 			return len;

 		i += len;
